1#include <stdio.h>
2#include <string.h>
3#include <stdbool.h>
4
5bool check_palindrome(char *text) {
6
7    int len = strlen(text);
8
9    // if the string is empty or contains a single character,
10    // the string is a palindrome
11    if (len == 0 || len == 1) {
12        return true;
13    }
14
15    // check if the first and last characters are the same
16    if (text[0] == text[len - 1]) {
17
18        char subtext[len - 1];
19
20        // copy text string to subtext string by
21        // excluding first and last characters
22        strncpy(subtext, text + 1, len - 2);
23
24        // ensure the new substring is null-terminated
25        subtext[len - 2] = '\0';
26
27        return check_palindrome(subtext);
28    }
29    else {
30        return false;
31    }
32}
33
34int main() {
35
36    bool result = check_palindrome("level");
37    printf("%s", result ? "Palindrome" : "Not Palindrome");
38
39    return 0;
